Random sampling of $\gamma_{(v,u)}$ over $\HH$ has been shown to produce graph lifts with favorable expansion properties \cite{Marcus2015I,Chandrasekaran2017,Hall_2018,Agarwal2016,Jeronimo2021}, which can be used to construct \emph{high dimensional expanders} (HDXs) \cite{DHLV2022,PK2022Good,QuantumTanner2022,Dinur2024sheaf,RSV2019,GJ2026,BLN2026,CHLT2026}. We only introduce ne approach that generalizes the above construction of the 1-dimensional complex $X$ to $t$ dimensions:
\begin{enumerate}
	\item Consider the $t$-dimensional Cartesian product: 
	\begin{align}
		(h,v_1, \ldots,v_t; b_1, \ldots,b_t) \in \HH \times V_0 \times \cdots \times V_0 \times \{0,1\} \times \cdots \times \{0,1\}.  
	\end{align}
	Here, $(b_1, \ldots,b_t)$ is a binary string. Let us abbreviate $(h,v_1, \ldots,v_j, \ldots,v_t)$ by $g$ and define
	\begin{align}
		X(0) \coloneq \{ [g; (b_j)_{j \in [t]} ] = (h,v_1, \ldots,v_t;b_1, \ldots,b_t) \} = \HH \times V_0^t \times \{0,1\}^t = \G \times \{0,1\}^t
	\end{align}
	as the collection of $0$-cubes or vertices. 	

	\item To define $X(1)$, we replace $A$ with $t$ families $A_j = (a_j^1, \ldots,a_j^n)$ with $j = 1, \ldots,t$. They act on $h$ and the corresponding components of the Cartesian product as follows:
	\begin{align}\label{eq:generator_action}
		a_j^{\mu} \cdot (h,v_1, \ldots,v_j, \ldots,v_t; b_1, \ldots,b_j, \ldots,b_t) 
		= (\gamma_{(v_j, v_j')} \cdot h,v_1, \ldots,v_j', \ldots,v_t; b_1, \ldots,1-b_j, \ldots,b_t).
	\end{align} 
	Here, $(v_j,v_j')$ is the $\mu$-th edge incident with $v_j$. Then
	\begin{align}
		\begin{aligned}
			X(1) \coloneq & \Big\{ \Big( [g; (b_j)_{j \in [t]} ], \ [a_i \cdot g; \{1-b_i\} \cup (b_j)_{j \neq i} ]  \Big): [g; (b_j)_{j \in [t]} ] \in X(0), a_i \in A_i \Big\}.
		\end{aligned}
	\end{align}
	For simplicity, we write
	\begin{align}
		[g; a_i, (b_j)_{j \neq i} ] = \Big( [g; b_i = 0, (b_j)_{j \neq i} ], [a_i \cdot g; b_i = 1, (b_j)_{j \neq i} ] \Big). 
	\end{align}

	\item More generally, let $S \subset [t]$ satisfy $\vert S \vert = p$. A $p$-cube $[g; (a_i)_{i \in S}, (b_j)_{j \in S^c} ]$ in $X(p)$ is defined as the product of edges $\prod_{i \in S} [g; a_i, (b_j)_{j \neq i} ]$. By definition, 
	\begin{align}\label{eq:system_size}
		\vert \G \vert = \vert \HH \times V_0 \times \cdots \times V_0 \vert = \vert \HH \vert \cdot \vert V_0 \vert^t,
	\end{align}
	Since for each $i \in [t]$, $\vert A_i \vert = n$, we have $\vert X(p) \vert = \binom{t}{p} 2^{t-p} n^p \vert \G \vert$. If we place physical qudits on $1$-cubes, the system size is $N = t 2^{t-1} n \vert \G \vert$.
\end{enumerate}

Throughout this paper, we would stick with 2-dimensional examples: for any $g = (h,v_1,v_2)$, the square below is a fundamental building block of $X$. For example, the $0$-cube $[g;0,0]$ is contained in the 1-cubes $[g;a_1,0]$ and $[g;0,a_2]$, both of which belong to the 2-cube $[g;a_1,a_2]$. The same construction extends to higher-dimensional cubes. Accordingly, $X$ is referred to as a \emph{cubical complex}. 

